    import '@/assets/sass/authentication/auth-boxed.scss';
    import axios from "axios";
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Login' });
    import { useRouter } from 'vue-router';
    const router = useRouter();


    const toastref = ref(null);
    const pwd_type = ref('password');
    const loading_spinner= ref(false);
    const username = ref("");
    const password = ref("");
    const error = ref({ })
    const sendNotification = inject('sendGroupNotification')
    const whatsappAlert = inject('whatsappAlert');
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const axiosInstance2 = axios.create({
        baseURL: process.env.VUE_APP_USER_DIRECTORY_API_BASE_URL
    });

        const getDeviceId = () => {
            let deviceId = localStorage.getItem('device_id');
            if (!deviceId) {
                deviceId = globalThis.crypto?.randomUUID?.() ?? `device-${Date.now()}-${Math.random().toString(36).slice(2)}`;
                localStorage.setItem('device_id', deviceId);
            }
            return deviceId;
        };

        const  login = async () => {
      loading_spinner.value = true;
        try {
        const response = await axiosInstance2.post(
          "/login", 
          {
            device_id: getDeviceId(),
            login: username.value,
            password:password.value,
          }
        );

        // showMessage('Welcome Back '+response.data.user.username)
        // console.log(response.data.user.uuid)

        const response2 = await axiosInstance.post(
          "/user/login", 
          {
           uuid : response.data.user.uuid
          }
        );

        if (response2.data.token) {
          showMessage("Welcome Back! " + response2.data.user.name);
          sendNotification('Login !', response2.data.user.name + ' just logged In','LOGIN')
          localStorage.setItem('token', response2.data.token);
          localStorage.setItem('user', JSON.stringify(response2.data.user));
          if(软.value.locked == true){
             router.push(软.value.path)
          }else{
           router.push(`${response2.data.user.path}`);
          }
        }
      } catch (error) {
         console.log(error)
         showError(error.response.data.message)
