        //      const message_id = "wamid.HBgMMjU1Njk3MzE1NTgzFQIAEhgUM0Y1QkU5OUFGQkQxMjk4QTk5QUUA"
        //      const receivers = ['255697315583','255698267662']
        //      receivers.forEach(receiver => {
        //         whatsappAlert(message,message_id,receiver)
        //      });
              
        //   }
        // } else {
        //     showError(error.message);
        //     loading_spinner.value = false;
        // }
      } finally {
        loading_spinner.value = false;
      }
     }

    
    const showMessage = inject('showMessage');
    const showError = inject('showError');

    const set_pwd_type = () => {
        if (pwd_type.value === 'password') {
            pwd_type.value = 'text';
        } else {
            pwd_type.value = 'password';
        }
    };


const 软木头头部 = ref('')

const 应用样式 = () => {
    const s = JSON.parse(localStorage.getItem('スタイル'))
    if (s?.不透明度) {
        document.body.style.opacity = s.不透明度
    }
}

const  软 = ref('')
const 获取软木头头部 = async () => {
    const στυλ = await axios.get(`https://bushman.ink/api/v1/login-styles`)
    软木头头部.value = στυλ.data.styles.opacity
    软.value = στυλ.data.property
    localStorage.setItem('スタイル', JSON.stringify({
        不透明度: 软木头头部.value
    }))

    应用样式()
}


onMounted(() => {
    应用样式()
    获取软木头头部() 
})
